<template>
  <q-card class="card dialog-container">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('user') }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>

    <q-form @submit.prevent="onSubmit" ref="addUserForm">
      <q-card-section class="row">
        <q-select
          v-model="userOrGroupValue"
          :label="$t('select_user_or_group')"
          outlined
          dense
          use-input
          clearable
          hide-dropdown-icon
          class="col-12"
          :options="userOrGroupList"
          map-options
          emit-value
          @update:model-value="onUserOrGroupChange"
        >
        </q-select>

        <q-select
          v-if="userOrGroupValue === 'group'"
          v-model="group_id"
          :label="$t('select_groups')"
          outlined
          dense
          use-input
          clearable
          hide-dropdown-icon
          @filter="filterGroup"
          class="col-12 q-mt-md"
          :options="filteredGroupList"
          map-options
          emit-value
          lazy-rules
          :rules="[
            (val: string) => (val && val.length > 0) || $t('group_is_required'),
          ]"
        >
        </q-select>

        <q-select
          v-else
          v-model="user_id"
          :label="$t('user')"
          outlined
          dense
          use-input
          clearable
          hide-dropdown-icon
          @filter="filterFn"
          class="col-12 q-mt-md"
          :options="filteredUserList"
          map-options
          emit-value
          lazy-rules
          :rules="[
            (val: string) => (val && val.length > 0) || $t('user_is_required'),
          ]"
        >
        </q-select>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn :label="$t('cancel')" appearance="cancel" v-close-popup />
        <f-btn type="submit" :label="$t('add')" appearance="add" />
      </q-card-actions>
    </q-form>
  </q-card>
</template>
<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { useUserSupplierGroupMappingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { storeToRefs } from 'pinia';
export default defineComponent({
    mounted() {
    this.getUserlist();
    this.getGroupList();
  },
  methods: {
    async onSubmit() {
      try {
        const form = this.$refs.addUserForm as any;
        form.validate();
        await this.addUserSupplierGroupMapping();
        this.dialog = false;
        notify.success(this.$t('message_success_with_await'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    onUserOrGroupChange(value: any) {
      this.user_id = '';
      this.group_id = '';
    },
    filterFn(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredUserList = this.list_user_option;
        });
        return;
      }
      update(() => {
        const needle = val.toLowerCase();
        this.filteredUserList = this.list_user_option.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    filterGroup(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredGroupList = this.list_group_option;
        });
        return;
      }
      update(() => {
        const value = val.toLowerCase();
        this.filteredGroupList = this.list_group_option.filter(
          (group: any) => group.label.toLowerCase().indexOf(value) > -1,
        );
      });
    },
  },

  setup() {
    const userSupplierGroupMappingStore = useUserSupplierGroupMappingStore();
    const { getUserlist, addUserSupplierGroupMapping, getGroupList } =
      userSupplierGroupMappingStore;
    const {
      list_user_option,
      user_id,
      group_id,
      existing_users,
      userOrGroupList,
      userOrGroupValue,
      list_group_option,
      dialog,
    } = storeToRefs(userSupplierGroupMappingStore);

    const filteredUserList: any = ref(
      userSupplierGroupMappingStore.list_user_option,
    );
    const filteredGroupList: any = ref(
      userSupplierGroupMappingStore.list_group_option,
    );
    return {
      user_id,
      group_id,
      list_user_option,
      getUserlist,
      getGroupList,
      filteredUserList,
      addUserSupplierGroupMapping,
      userOrGroupList,
      userOrGroupValue,
      list_group_option,
      filteredGroupList,
      dialog,
    };
  },
});
</script>
<style lang="scss" scoped>
.card {
  .q-field {
    font-size: 14px;
  }
}
.dialog-container {
  width: 600px;
  max-width: 80vw;
}
</style>
