<template>
  <div class="page-container page-height-limit">
    <div class="settings-page-content">
      <docbits-accordion-panel
        v-for="group in supplier_group_mapping_list"
        :key="group.id"
        v-model="expandedSections[group.id]"
        icon="mdi:account-outline"
        :title="`${group.title} (${userAndGroupCount(group.users?.length, group.groups?.length)})`"
        bodyClass="settings-card"
      >
        <div>
          <div class="flex items-center justify-end p-2">
            <f-btn
              icon="add"
              :label="$t('new')"
              @click="openDialog(group.id, group.users, group.groups)"
            />
          </div>
          <DocBitsTable
            :rows="getMappingRows(group)"
            :columns="mappingColumns"
            :row-actions="rowActions"
            row-key="rowId"
            :features="{ sorting: false, pagination: false, rowActions: true }"
            dense
            @row-action="onRowAction($event, group.id)"
          >
            <template #body-cell-name="{ row }">
              {{ row.displayName }}
              <q-icon v-if="row.type === 'group'" name="people" size="16px" class="q-ml-sm" />
            </template>
          </DocBitsTable>
        </div>
      </docbits-accordion-panel>
    </div>
  </div>

  <q-dialog v-model="dialog">
    <Create />
  </q-dialog>

  <q-dialog v-model="confirmDeleteDialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteUser()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { defineComponent, ref, reactive } from 'vue';
import { notify } from 'src/components/notifications/notify';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import { useUserSupplierGroupMappingStore } from 'src/store/main';
import type { UnifiedTableColumn, RowActionItem } from 'src/components/Table';
import Create from 'src/pages/Settings/UserAndSupplierGroupMapping/Create.vue';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Create,
    Loader,
    DocBitsTable,
  },
  mounted() {
    this.getUserSupplierGroupMappingAsSelectList();
    this.getUserlist();
  },
  watch: {
    loading: {
      deep: true,
      handler: function (newVal, oldVal) {
        if (newVal) {
          this.showLoading();
        } else {
          this.hideLoading();
        }
      },
    },
  },
  computed: {
    mappingColumns(): UnifiedTableColumn[] {
      return [
        { name: 'name', label: this.$t('name'), field: 'displayName', align: 'left' as const },
      ];
    },
    rowActions(): RowActionItem[] {
      return [
        {
          key: 'delete',
          label: this.$t('delete'),
          icon: 'delete',
          color: 'negative',
        },
      ];
    },
  },
  methods: {
    getMappingRows(group: any) {
      const rows: any[] = [];
      if (group.groups) {
        for (const g of group.groups) {
          rows.push({ rowId: `group-${g.id}`, type: 'group', entityId: g.id, displayName: g.name });
        }
      }
      if (group.users) {
        for (const u of group.users) {
          rows.push({ rowId: `user-${u.user_id}`, type: 'user', entityId: u.user_id, displayName: `${u.first_name} ${u.last_name}` });
        }
      }
      return rows;
    },
    onRowAction(event: any, groupId: string) {
      if (event.action === 'delete') {
        this.openDeleteDialog(groupId, event.row.entityId, event.row.type);
      }
    },
    openDialog(
      supplier_group_id: string | null,
      existing_users: any[] | null,
      existing_group: any[] | null,
    ) {
      this.dialog = true;
      this.supplier_group_id = supplier_group_id as string;
      this.existing_users = existing_users;
      this.existing_group = existing_group;
      this.userOrGroupValue = '';
      this.user_id = '';
      this.group_id = '';
    },
    openDeleteDialog(
      supplier_group_id: string,
      user_or_group_id: string,
      type: string,
    ) {
      this.confirmDeleteDialog = true;
      this.supplier_group_id = supplier_group_id;
      if (type === 'user') {
        this.user_id = user_or_group_id;
        this.group_id = '';
      } else {
        this.group_id = user_or_group_id;
        this.user_id = '';
      }
    },
    async deleteUser() {
      try {
        await this.deleteUserSupplierGroupMapping();
        notify.success(this.$t('message_success_with_await'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
      }
    },
    userAndGroupCount(user: any, group: any) {
      return ((user ? user : 0) + (group ? group : 0)) as string;
    },
  },
  setup() {
    const userSupplierGroupMappingStore = useUserSupplierGroupMappingStore();
    const {
      getUserSupplierGroupMappingAsSelectList,
      getUserlist,
      deleteUserSupplierGroupMapping,
    } = userSupplierGroupMappingStore;
    const {
      supplier_group_mapping_list,
      loading,
      dialog,
      existing_users,
      existing_group,
      confirmDeleteDialog,
      user_id,
      group_id,
      supplier_group_id,
      userOrGroupValue,
    } = storeToRefs(userSupplierGroupMappingStore);
    return {
      loading,
      supplier_group_mapping_list,
      getUserSupplierGroupMappingAsSelectList,
      getUserlist,
      dialog,
      existing_users,
      existing_group,
      confirmDeleteDialog,
      deleteUserSupplierGroupMapping,
      user_id,
      group_id,
      supplier_group_id,
      userOrGroupValue,
      expandedSections: reactive({} as Record<string, boolean>),
    };
  },
});
</script>
